package app.layan.test;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.*;import android.view.*;import android.widget.*;import app.layan.quran.*;import java.io.*;import org.json.*;
/** Verify every guide is complete and its actual readable dialog opens on the installed APK. */
public final class QiraatFullGuideRegression extends Instrumentation {
 private int checks;
 public void onCreate(Bundle args){super.onCreate(args);start();}
 private void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
 private void ui(Runnable r){runOnMainSync(r);waitForIdleSync();}
 private String contents(View view){String text=view instanceof TextView?((TextView)view).getText().toString():"";if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)text+=contents(((ViewGroup)view).getChildAt(i));return text;}
 private void screenshot(Activity a,String name)throws Exception{SystemClock.sleep(200);Bitmap b=NativeScreens.capture(this,a);File dir=a.getExternalFilesDir("tests");dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
 private void installSource(String id)throws Exception{if(QiraatData.downloaded(getTargetContext(),id))return;JSONObject m=QiraatData.metadata(getTargetContext(),id);String url=m.getString("url");File archive=new File("/data/local/tmp/qiraat-corpus",url.substring(url.lastIndexOf('/')+1));check(QiraatDownload.sha(archive).equals(m.getString("downloadSha256")),"Pinned compressed source "+id);File dir=QiraatData.directory(getTargetContext());dir.mkdirs();QiraatDownload.install(archive,dir,id,m.getLong("bytes"),m.getString("sha256"),(p,s)->{});}
 private QiraatReaderActivity launch(String id,int page)throws Exception{QiraatReaderActivity a=(QiraatReaderActivity)startActivitySync(new Intent(getTargetContext(),QiraatReaderActivity.class).putExtra("riwayah",id).putExtra("page",page).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));long end=SystemClock.elapsedRealtime()+120000;while(SystemClock.elapsedRealtime()<end){boolean[] ready={false};ui(()->ready[0]=a.currentPageReady());if(ready[0]){ui(()->{check(a.findViewById(QiraatReaderActivity.HEADER).getVisibility()==View.GONE,"Reader starts without toolbar "+id);check((a.getWindow().getDecorView().getSystemUiVisibility()&View.SYSTEM_UI_FLAG_FULLSCREEN)!=0,"Reader starts full screen "+id);});return a;}SystemClock.sleep(100);}throw new AssertionError("Source page not ready: "+id);}
 public void onStart(){Bundle result=new Bundle();try{
  Context c=getTargetContext();android.preference.PreferenceManager.getDefaultSharedPreferences(c).edit().putBoolean("nightMode",false).putBoolean("useArabicNames",true).commit();JSONArray all=QiraatData.catalog(c).getJSONArray("riwayat");check(all.length()==20,"Exactly twenty readings");
  for(int i=0;i<all.length();i++){
   String id=all.getJSONObject(i).getString("id");JSONObject g=QiraatData.json(c,"guides/"+id+".json");check(g.getJSONObject("coverageAudit").getBoolean("allGuideExplanationsComplete"),"Complete guide "+id);check(g.getJSONObject("coverageAudit").getJSONArray("unresolved").length()==0,"No unresolved entries "+id);
   JSONArray items=g.getJSONArray("items");for(int j=0;j<items.length();j++){JSONObject item=items.getJSONObject(j);check(item.getBoolean("verified")&&item.getString("meaning").length()>15&&item.getString("short").length()>0,"Full meaningful entry "+id+" "+j);check(!item.toString().contains("غير موثّق"),"No placeholder "+id);}
   check(g.getJSONArray("basicDiacritics").length()==12&&g.getJSONArray("stopSigns").length()==7,"Full basic and stop signs "+id);JSONArray pages=g.getJSONArray("pagePaints");check(pages.length()==604,"Complete page table "+id);JSONObject map=g.getJSONObject("paintMappings");for(int p=0;p<604;p++){JSONArray paints=pages.getJSONArray(p);for(int j=0;j<paints.length();j++){String paint=paints.getString(j);JSONObject item=items.getJSONObject(map.getInt(paint));check(paint.startsWith(item.getString("color")+":"),"Exact source swatch "+id+" "+p);}}
   installSource(id);int page=id.equals("duri-kisai")?13:id.equals("ibn-wardan")?49:id.equals("qaloon")?6:id.equals("ishaq")?61:300;QiraatReaderActivity a=launch(id,page);AlertDialog[] dialog={null};ui(()->dialog[0]=QiraatGuide.showAll(a,id,page));ui(()->{View body=dialog[0].findViewById(QiraatGuide.DETAIL_BODY);check(body!=null,"Actual complete dialog "+id);String text=contents(body);check(text.contains(g.optString("nameArabic"))&&text.contains("علامات الضبط")&&text.contains("علامات الوقف"),"Correct reading and all explanation sections "+id);check(!text.contains("غير موثّق")&&!text.contains("تعذّر"),"Readable full dialog "+id);ScrollView scroll=(ScrollView)body.getParent();check(scroll.getChildAt(0).getHeight()>0,"Laid-out scrollable full explanation "+id);});
   if(id.equals("warsh")||id.equals("duri-kisai")||id.equals("ibn-wardan")||id.equals("hafs"))screenshot(a,"complete-guide-"+id);ui(dialog[0]::dismiss);if(id.equals("duri-kisai")||id.equals("ibn-wardan")||id.equals("qaloon")||id.equals("ishaq"))screenshot(a,"complete-page-"+id);ui(a::finish);android.util.Log.i("LayanFullGuide","PASS actual full guide "+id);
  }
  android.preference.PreferenceManager.getDefaultSharedPreferences(c).edit().putBoolean("nightMode",true).commit();QiraatReaderActivity a=launch("warsh",300);AlertDialog[] dialog={null};ui(()->dialog[0]=QiraatGuide.showAll(a,"warsh",300));screenshot(a,"complete-guide-warsh-night");ui(dialog[0]::dismiss);ui(a::finish);
  result.putString("result","PASS "+checks+" assertions: all twenty complete installed guides; 12080 source-page mappings; every full explanation dialog; basic and stop signs; actual Arabic day and night views");finish(Activity.RESULT_OK,result);
 }catch(Throwable error){result.putString("error",android.util.Log.getStackTraceString(error));finish(Activity.RESULT_CANCELED,result);}}
}
